'use strict';

function diffNotes(local, remote) {
  const toUpload = local.filter((n) => !remote.some((r) => r.id === n.id && r.rev >= n.rev));
  const toDownload = remote.filter((r) => !local.some((n) => n.id === r.id && n.rev >= r.rev));
  return { toUpload, toDownload };
}

module.exports = { diffNotes };

