'use strict';

const fs = require('fs');
const api = require('./api');
const { diffNotes } = require('./diff');

async function sync(dir) {
  const files = fs.readdirSync(dir).filter((f) => f.endsWith('.json'));
  const local = files.map((f) => JSON.parse(fs.readFileSync(`${dir}/${f}`, 'utf8')));
  const remote = await api.listNotes();
  const { toUpload, toDownload } = diffNotes(local, remote);
  for (const n of toUpload) await api.putNote(n);
  for (const n of toDownload) fs.writeFileSync(`${dir}/${n.id}.json`, JSON.stringify(n));
  return { uploaded: toUpload.length, downloaded: toDownload.length };
}

module.exports = { sync };

